/**
 * Where a thing set on a piece rests, part by part over its top: a grid of measured rest heights over the collider's
 * outline in the piece's own frame (palette/restGrids.ts, generated by `npm run render -- rests`). A piece's top is
 * rarely one flat surface: a chest's rounded lid holds things only along its crest, an anvil's face stands over its
 * horn, a desk's top ends at its edge and an altar's carved back rises behind its slab. A thing set anywhere but a part
 * that holds it floats over a slope or falls off an edge.
 *
 * The rule is the support piece's, read where the thing finally stands (compile/realize/settle.ts turns the thing's
 * point into the support's frame with util/turn.ts): a piece never measured has no grid, and things on it keep the one
 * height they were given.
 */
import { MEASURED_REST_GRIDS } from "./restGrids";

/** A measured rest grid: cells along x and z, and each cell's rest height above the collider's bottom (null: none). */
export interface RestGrid {
  readonly nx: number;
  readonly nz: number;
  /** Row by row from the outline's min z, each from its min x (tiles). */
  readonly heights: ReadonlyArray<number | null>;
}

const parsed = new Map<string, RestGrid | null>();

/** Parses one table entry ("<nx>x<nz>:" and heights in hundredths, "-" for none), or null when malformed. */
export function parseRestGrid(text: string): RestGrid | null {
  const m = /^(\d+)x(\d+):(.*)$/.exec(text);
  if (!m) return null;
  const nx = Number(m[1]);
  const nz = Number(m[2]);
  const heights = (m[3] ?? "").split(" ").map((s) => (s === "-" ? null : Number(s) / 100));
  if (heights.length !== nx * nz || heights.some((h) => h !== null && !Number.isFinite(h))) return null;
  return { nx, nz, heights };
}

/** The measured rest grid of an asset, or undefined when it was never measured. */
export function restGridOf(asset: string): RestGrid | undefined {
  const id = asset.toLowerCase();
  if (!parsed.has(id)) {
    const text = Object.hasOwn(MEASURED_REST_GRIDS, id) ? MEASURED_REST_GRIDS[id] : undefined;
    parsed.set(id, text === undefined ? null : parseRestGrid(text));
  }
  return parsed.get(id) ?? undefined;
}

/** A point on a piece's top that holds a thing: its place in the piece's frame and the height it rests at. */
export interface RestSpot {
  /** In the piece's own frame, from the collider's centre (tiles). */
  readonly lx: number;
  readonly lz: number;
  /** Above the collider's bottom (tiles). */
  readonly rest: number;
  /** How far the spot is from the point asked about (tiles; 0 when the point itself holds). */
  readonly moved: number;
}

/**
 * Where a thing at (lx, lz) in the piece's frame (from its collider's centre; the collider is `sx` by `sz`) rests: the
 * cell under it when that cell holds things, else the nearest holding cell's centre (a thing never hangs over an edge
 * or a slope). Null when no cell of the top holds a thing.
 */
export function restSpot(grid: RestGrid, sx: number, sz: number, lx: number, lz: number): RestSpot | null {
  const cw = sx / grid.nx;
  const cd = sz / grid.nz;
  const i0 = Math.min(grid.nx - 1, Math.max(0, Math.floor((lx + sx / 2) / cw)));
  const k0 = Math.min(grid.nz - 1, Math.max(0, Math.floor((lz + sz / 2) / cd)));
  const here = grid.heights[k0 * grid.nx + i0];
  const inside = Math.abs(lx) <= sx / 2 && Math.abs(lz) <= sz / 2;
  if (here !== null && here !== undefined && inside) return { lx, lz, rest: here, moved: 0 };
  let best: RestSpot | null = null;
  for (let k = 0; k < grid.nz; k++)
    for (let i = 0; i < grid.nx; i++) {
      const h = grid.heights[k * grid.nx + i];
      if (h === null || h === undefined) continue;
      const cx = -sx / 2 + (i + 0.5) * cw;
      const cz = -sz / 2 + (k + 0.5) * cd;
      const d = Math.hypot(cx - lx, cz - lz);
      // ties go to the higher surface (the main top over a lower ledge)
      if (!best || d < best.moved - 1e-9 || (Math.abs(d - best.moved) <= 1e-9 && h > best.rest))
        best = { lx: cx, lz: cz, rest: h, moved: d };
    }
  return best;
}
